import React, { useState } from 'react';
import './App.css';
import Navbar from './Navbar';
import ProductCard from './ProductCard';

function App() {
  const [cart, setCart] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const products = [
    { id: 1, name: 'Classic Leather Journal', price: 1299, image: 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=500' },
    { id: 2, name: 'Premium Fountain Pen', price: 2499, image: 'https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?w=500' },
    { id: 3, name: 'Hardcover Sketchbook', price: 899, image: 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=500' },
    { id: 4, name: 'Gold Leaf Bookmark', price: 450, image: 'https://images.unsplash.com/photo-1541963463532-d68292c34b19?w=500' }
  ];

  const addToCart = (product) => {
    setCart((prevCart) => {
      const existingProduct = prevCart.find(item => item.id === product.id);
      if (existingProduct) {
        return prevCart.map(item =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prevCart, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId) => {
    setCart((prevCart) => prevCart.filter(item => item.id !== productId));
  };

  const totalCartItems = cart.reduce((total, item) => total + item.quantity, 0);
  const totalPrice = cart.reduce((total, item) => total + (item.price * item.quantity), 0);

  return (
    <div className="app-container">
      <Navbar cartCount={totalCartItems} onCartClick={() => setIsCartOpen(!isCartOpen)} />

      <header className="hero-section">
        <h1>Sunanda Pages</h1>
        <p>Premium Journals & Fine Writing Instruments</p>
      </header>

      <main className="main-content">
        <div className="product-grid">
          {products.map(product => (
            <ProductCard key={product.id} product={product} onAddToCart={addToCart} />
          ))}
        </div>

        {isCartOpen && (
          <div className="cart-overlay">
            <div className="cart-modal">
              <h2>Your Shopping Cart</h2>
              <button className="close-btn" onClick={() => setIsCartOpen(false)}>×</button>

              {cart.length === 0 ? (
                <p className="empty-message">Your cart is feeling a bit light!</p>
              ) : (
                <>
                  <div className="cart-items-list">
                    {cart.map(item => (
                      <div key={item.id} className="cart-item">
                        <div>
                          <h4>{item.name}</h4>
                          <p>₹{item.price} x {item.quantity}</p>
                        </div>
                        <button className="remove-btn" onClick={() => removeFromCart(item.id)}>Remove</button>
                      </div>
                    ))}
                  </div>
                  <div className="cart-summary">
                    <h3>Total: ₹{totalPrice}</h3>
                    <button className="checkout-btn" onClick={() => alert('Proceeding to checkout!')}>Checkout Now</button>
                  </div>
                </>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
